window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-77d121b7da243fce"]={"versions": [{"id": "FIG-77d121b7da243fce", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC-Metamodell) für den Diagnostic Event Manager (<code>Dem</code>) im Classic-Platform-Architekturkontext der BSW (System Services). Das Diagramm definiert die Konfigurationsstruktur für Betriebszyklen (<code>DemOperationCycle</code>) innerhalb des allgemeinen Parametercontainers <code>DemGeneral</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst Container- und Parameterdefinitionen:</p>\n<ul class=\"fig-list\"><li><code>DemGeneral</code>: <code>EcucParamConfContainerDef</code> (Multiplizität 1..1) als übergeordneter Container.\n</li><li><code>DemOperationCycle</code>: <code>EcucParamConfContainerDef</code> (Multiplizität 1..256), über Komposition <code>+subContainer</code> in <code>DemGeneral</code> eingebunden.\n</li><li><code>DemOperationCycleType</code>: <code>EcucEnumerationParamDef</code> (Multiplizität 1..1), über Komposition <code>+parameter</code> an <code>DemOperationCycle</code> angebunden. Enthält über <code>+literal</code> sechs Literale (<code>EcucEnumerationLiteralDef</code>): <code>DEM_OPCYC_IGNITION</code>, <code>DEM_OPCYC_OBD_DCY</code>, <code>DEM_OPCYC_WARMUP</code>, <code>DEM_OPCYC_POWER</code>, <code>DEM_OPCYC_OTHER</code>, <code>DEM_OPCYC_TIME</code>.\n</li><li><code>DemOperationCycleAutostart</code>: <code>EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>), über <code>+parameter</code> an <code>DemOperationCycle</code> angebunden.\n</li><li><code>DemOperationCycleAutomaticEnd</code>: <code>EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>), über <code>+parameter</code> an <code>DemOperationCycle</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell für die Konfigurationsbeschreibung definiert das Diagramm keinen direkten Laufzeit- oder Sequenzablauf. Die konfigurierten Parameter steuern jedoch das Betriebszyklus-Management des Dem zur Laufzeit: <code>DemOperationCycleAutostart</code> bestimmt, ob der Zyklus beim Start des Dem automatisch aktiviert wird, und <code>DemOperationCycleAutomaticEnd</code> legt fest, ob der Zyklus bei Beendigung des Dem bzw. beim Herunterfahren automatisch beendet wird. Der Typ <code>DemOperationCycleType</code> ordnet dem Zyklus das auslösende Ereignis bzw. die Zyklusdomäne (z. B. Zündung, OBD Driving Cycle, Warmup, Zeit oder Power) zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für Dem-Implementierungen und BSW-Generatoren. Jeder konfigurierte Betriebszyklus muss genau einen Typen aus der vorgegebenen Literal-Menge besitzen und explizit für Autostart und automatisches Beenden konfiguriert werden (Standard jeweils <code>false</code>). Bis zu 256 Betriebszyklen können instanziiert werden (Multiplizität 1..256), wobei mindestens ein Betriebszyklus definiert sein muss.</p>"}, {"id": "FIG-ce5bf1cc156880b3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC-Metamodell) für den Diagnostic Event Manager (<code>Dem</code>) im Classic-Platform-Architekturkontext der BSW (System Services). Das Diagramm definiert die Konfigurationsstruktur für Betriebszyklen (<code>DemOperationCycle</code>) innerhalb des allgemeinen Parametercontainers <code>DemGeneral</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst Container- und Parameterdefinitionen:</p>\n<ul class=\"fig-list\"><li><code>DemGeneral</code>: <code>EcucParamConfContainerDef</code> (Multiplizität 1..1) als übergeordneter Container.\n</li><li><code>DemOperationCycle</code>: <code>EcucParamConfContainerDef</code> (Multiplizität 1..256), über Komposition <code>+subContainer</code> in <code>DemGeneral</code> eingebunden.\n</li><li><code>DemOperationCycleType</code>: <code>EcucEnumerationParamDef</code> (Multiplizität 1..1), über Komposition <code>+parameter</code> an <code>DemOperationCycle</code> angebunden. Enthält über <code>+literal</code> sechs Literale (<code>EcucEnumerationLiteralDef</code>): <code>DEM_OPCYC_IGNITION</code>, <code>DEM_OPCYC_OBD_DCY</code>, <code>DEM_OPCYC_WARMUP</code>, <code>DEM_OPCYC_POWER</code>, <code>DEM_OPCYC_OTHER</code>, <code>DEM_OPCYC_TIME</code>.\n</li><li><code>DemOperationCycleAutostart</code>: <code>EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>), über <code>+parameter</code> an <code>DemOperationCycle</code> angebunden.\n</li><li><code>DemOperationCycleAutomaticEnd</code>: <code>EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>), über <code>+parameter</code> an <code>DemOperationCycle</code> angebunden.\n</li><li><code>DemOperationCycleId</code>: <code>EcucIntegerParamDef</code> (Multiplizität 0..1, <code>symbolicNameValue = true</code>), über Komposition <code>+parameter</code> an <code>DemOperationCycle</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell für die Konfigurationsbeschreibung definiert das Diagramm keinen direkten Laufzeit- oder Sequenzablauf. Die konfigurierten Parameter steuern jedoch das Betriebszyklus-Management des Dem zur Laufzeit: <code>DemOperationCycleAutostart</code> bestimmt, ob der Zyklus beim Start des Dem automatisch aktiviert wird, und <code>DemOperationCycleAutomaticEnd</code> legt fest, ob der Zyklus bei Beendigung des Dem bzw. beim Herunterfahren automatisch beendet wird. Der Typ <code>DemOperationCycleType</code> ordnet dem Zyklus das auslösende Ereignis bzw. die Zyklusdomäne (z. B. Zündung, OBD Driving Cycle, Warmup, Zeit oder Power) zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für Dem-Implementierungen und BSW-Generatoren. Jeder konfigurierte Betriebszyklus muss genau einen Typen aus der vorgegebenen Literal-Menge besitzen und explizit für Autostart und automatisches Beenden konfiguriert werden (Standard jeweils <code>false</code>). Über <code>DemOperationCycleId</code> kann optional (<code>0..1</code>) ein symbolischer Bezeichner als Integer-Wert zugewiesen werden (<code>symbolicNameValue = true</code>), um die Betriebszyklus-Referenzierung über symbolische C-Makros/Konstanten zu unterstützen. Bis zu 256 Betriebszyklen können instanziiert werden (Multiplizität 1..256), wobei mindestens ein Betriebszyklus definiert sein muss.</p>"}], "trans": [{"from": "FIG-77d121b7da243fce", "to": "FIG-ce5bf1cc156880b3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>DemOperationCycle: Parameter <code>DemOperationCycleId</code> (<code>EcucIntegerParamDef</code>) mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> und <code>symbolicNameValue = true</code> hinzugefügt.\n</li></ul>"}]};
